import{z as s,x as o,o as n,c as d,q as i,j as l,D as A,d as e,s as B,S as t,b as a}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"政策评估案例与收束","description":"","frontmatter":{"title":"政策评估案例与收束","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/pe-case-map.md","filePath":"econ/pe-case-map.md","lastUpdated":1791063341000}'),p={name:"econ/pe-case-map.md"};function D(m,E,c,T,u,h){const r=o("Mermaid");return n(),d("div",null,[E[2]||(E[2]=i('<h1 id="政策评估案例与收束" tabindex="-1">政策评估案例与收束 <a class="header-anchor" href="#政策评估案例与收束" aria-label="Permalink to &quot;政策评估案例与收束&quot;">​</a></h1><div class="epigraph"><p>评估的成熟不是多一种估计量，而是每一步都问：假设写了没有、目标对准了没有、证据搬不搬得动——案例是这三问的考场。</p><footer>—— 据 Card and Krueger, AER 1994；Abadie, Diamond and Hainmueller, JASA 2010；Finkelstein 等, QJE 2012 整理</footer></div><p><a href="/econ/pe-meta-analysis">上一课</a>把多研究的合成收成估计问题。本课收束全课程：先把三个案例放回工具箱里各走一遍，再按读序重排十课。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束不靠清单，靠案例。<strong>新泽西最低工资</strong>（Card–Krueger 1994）：两州两组的差中差发现就业未降，主干<a href="/econ/difference-in-differences">双重差分</a>以其为教具；它的后续推进全在对照的构造——相邻县洗掉区域趋势，一百多次上调的窗口读数把「受影响岗位的净损失」当作读数；两代文献的缠斗与元回归的收口在<a href="/econ/minimum-wage-debates">最低工资：两代文献</a>。一个案例走过 DiD、预趋势、交错修正与 meta 全链条。<strong>加州 99 号提案烟税与德国统一</strong>：一个处理单位、没有门槛，合成对照的教具；按本课程第一课的判据读它们——处理前拟合是前提、安慰剂排位是推断、邻州走私是 SUTVA 威胁——案例的每一步推进都来自把可行判据当真。<strong>俄勒冈医保抽签</strong>（Finkelstein 等 2012）：彩票给随机化，名额有限给不依从——参保率升约 25 个百分点是第一阶段，健康与财务结局的效应沿 ITT 报，TOT 是依从者 LATE；「有保险」到「健康」的链条被后续工作分段评估，依从课与决策课的语言在同一个案例里交接。</p><p><span class="marginnote">数字实例：俄勒冈「参保率升约 25 个百分点」说的是<strong>差值</strong>——比如参保率从 40% 涨到 65%，涨了 25 个百分点，但相对涨幅是 62.5%。「百分点」是两个百分比相减，「百分比」是相除；混用这两个词，效应会被放大或缩小好几倍。</span></p><p><span class="marginnote">三个案例的共同点：没有一个是因为「估计量先进」而推进了文献。最低工资赢在对照构造，烟税赢在可行判据，俄勒冈赢在设计契约写得干净——估计量只是把设计兑现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按读序重排全课程：</p><ul><li><a href="/econ/pe-synthetic-control-deep">合成对照的深化</a>：可行判据四条，修正方法与其代价。</li><li><a href="/econ/pe-eventstudy-specification">事件研究的规范</a>：参照期、端点归并、队列加权、预趋势当诊断。</li><li><a href="/econ/pe-staggered-did-revisions">交错 DiD 的最新修正</a>：诊断、定目标、选对照、显式聚合。</li><li><a href="/econ/pe-rdd-deep">断点回归的加深</a>：带宽敏感性、操纵 bundle、离散驱动元、外推声明。</li><li><a href="/econ/pe-iv-heterogeneous-compliers">工具变量的深化：异质依从</a>：LATE 是依从者的、工具特定的效应。</li><li><a href="/econ/pe-rct-design-analysis">RCT 的设计与分析</a>：设计效应预算、按设计分析、ITT 与 TOT。</li><li><a href="/econ/pe-decision-target">以决策为目标</a>：福利泛函、处理规则与后悔、试点的信息价值。</li><li><a href="/econ/pe-external-validity">外部有效性</a>：四道断点，搬运的是参数与分布不是单点效应。</li><li><a href="/econ/pe-meta-analysis">Meta 分析</a>：随机效应、两种筛子、异质性的元回归。</li></ul>',10)),(n(),l(t,null,{default:A(()=>[B(r,{id:"mermaid-72",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20DES%5B%22%E8%AE%BE%E8%AE%A1%3A%20%E8%AF%86%E5%88%AB%E5%A5%91%E7%BA%A6%22%5D%0A%20%20%20%20SC%5B%22%E5%90%88%E6%88%90%E5%AF%B9%E7%85%A7%E5%88%A4%E6%8D%AE%22%5D%20--%3E%20ES%5B%22%E4%BA%8B%E4%BB%B6%E7%A0%94%E7%A9%B6%E8%A7%84%E8%8C%83%22%5D%0A%20%20%20%20ES%20--%3E%20ST%5B%22%E4%BA%A4%E9%94%99%E4%BF%AE%E6%AD%A3%22%5D%0A%20%20%20%20ST%20--%3E%20RD%5B%22%E6%96%AD%E7%82%B9%E5%8A%A0%E6%B7%B1%22%5D%0A%20%20%20%20RD%20--%3E%20IV%5B%22%E5%BC%82%E8%B4%A8%E4%BE%9D%E4%BB%8E%22%5D%0A%20%20end%0A%20%20subgraph%20INF%5B%22%E6%8E%A8%E6%96%AD%3A%20%E4%BB%8E%E4%BC%B0%E8%AE%A1%E5%88%B0%E5%86%B3%E7%AD%96%22%5D%0A%20%20%20%20RCT%5B%22RCT%20%E8%AE%BE%E8%AE%A1%E5%A5%91%E7%BA%A6%22%5D%20--%3E%20DEC%5B%22%E5%86%B3%E7%AD%96%E7%9B%AE%E6%A0%87%22%5D%0A%20%20end%0A%20%20subgraph%20SYN%5B%22%E7%BB%BC%E5%90%88%3A%20%E4%BB%8E%E7%A0%94%E7%A9%B6%E5%88%B0%E8%AF%81%E6%8D%AE%E5%BA%93%22%5D%0A%20%20%20%20EXT%5B%22%E5%A4%96%E9%83%A8%E6%9C%89%E6%95%88%E6%80%A7%22%5D%20--%3E%20META%5B%22Meta%20%E5%88%86%E6%9E%90%22%5D%0A%20%20end%0A%20%20DES%20--%3E%20RCT%0A%20%20INF%20--%3E%20EXT%0A%20%20META%20--%3E%20CASE%5B%22%E6%A1%88%E4%BE%8B%3A%20%E8%AE%BE%E8%AE%A1%E5%85%91%E7%8E%B0%E4%BC%B0%E8%AE%A1%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("十课能收成三条主线。"),a("strong",null,"设计是识别契约"),e("：每类设计都给出一组假设与可证伪检查——合成对照的拟合判据、事件研究的参照期、交错的干净对照、断点的局部随机、IV 的单调性与排除、RCT 的分配机制；契约条款写进报告，估计量才可审计。"),a("strong",null,"推断对准目标"),e("：从估计量到目标参数（ITT、LATE、ATT\\((g,t)\\)、门槛效应）再到决策规则，每一步都要显式；名义水平、权重与错误不对称是这一段的常设检查点。"),a("strong",null,"证据是组合物"),e("：单研究的内部有效只是入场券，外推靠分布、调节结构与对筛子的校正；meta 把综合变成估计，案例把全部工具放回地面。")],-1)),E[5]||(E[5]=a("p",null,"不这么做会错在哪：把课程读成估计量目录，案例只会被当成应用题；三条主线断任何一条，评估都退化成「跑一个显著的回归」。",-1)),(n(),l(t,null,{default:A(()=>[B(r,{id:"mermaid-82",class:"mermaid",graph:"flowchart%20LR%0A%20%20CK%5B%22%E6%9C%80%E4%BD%8E%E5%B7%A5%E8%B5%84%20Card-Krueger%22%5D%20--%3E%20D1%5B%22%E8%AE%BE%E8%AE%A1%3A%20DiD%22%5D%0A%20%20D1%20--%3E%20K1%5B%22%E5%85%B3%E9%94%AE%E5%88%A4%E6%8D%AE%3A%20%E9%A2%84%E8%B6%8B%E5%8A%BF%E4%B8%8E%E5%AF%B9%E7%85%A7%E6%9E%84%E9%80%A0%22%5D%0A%20%20CA%5B%22%E5%8A%A0%E5%B7%9E%E7%83%9F%E7%A8%8E%20%2F%20%E5%BE%B7%E5%9B%BD%E7%BB%9F%E4%B8%80%22%5D%20--%3E%20D2%5B%22%E8%AE%BE%E8%AE%A1%3A%20%E5%90%88%E6%88%90%E5%AF%B9%E7%85%A7%22%5D%0A%20%20D2%20--%3E%20K2%5B%22%E5%85%B3%E9%94%AE%E5%88%A4%E6%8D%AE%3A%20%E5%A4%84%E7%90%86%E5%89%8D%E6%8B%9F%E5%90%88%E4%B8%8E%E5%AE%89%E6%85%B0%E5%89%82%22%5D%0A%20%20OR%5B%22%E4%BF%84%E5%8B%92%E5%86%88%E5%8C%BB%E4%BF%9D%E6%8A%BD%E7%AD%BE%22%5D%20--%3E%20D3%5B%22%E8%AE%BE%E8%AE%A1%3A%20RCT%20%2B%20%E4%B8%8D%E4%BE%9D%E4%BB%8E%22%5D%0A%20%20D3%20--%3E%20K3%5B%22%E5%85%B3%E9%94%AE%E5%88%A4%E6%8D%AE%3A%20%E7%AC%AC%E4%B8%80%E9%98%B6%E6%AE%B5%E4%B8%8E%20ITT%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=i('<p>上图回答的问题与读序图不同：读序图画「十课怎么排」，这张画「三个案例各自的设计契约与其关键检查点是什么」——每个案例的文献推进点都落在检查点上，而不是估计量上，这正呼应「估计量只是把设计兑现」这条收束判据。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>收束不是领域的边界：结构模型把「从未发生的规则」接走，那是下一门深钻课的事；本课程不越界去写它。<span class="marginnote">直觉类比：三问审计像搬家前量家具——内部有效只证明「这件家具在你旧家能用」，第三问「搬不搬得动」要量新家的门宽和楼道；跳过这一步，买家具新居放不下，外推效应落地就翻车。</span>三个案例也不构成「评估皆准」的证据——每个都留下未决的分布与边界，这正是把它们选进来的原因。读完本课程，默认的口径是：任何政策数字先问三问——假设、目标、搬运。</p><p>本课程到此收束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>案例的推进来自设计兑现：对照构造、可行判据、设计契约。</li><li>三条主线：设计是契约、推断对准目标、证据是组合物。</li><li>报告的审计口径是三问：假设写了没有、目标对准了没有、证据搬不搬得动。</li><li>估计量是设计的兑现，不是课程的中心。</li><li>出处：Card and Krueger, <em>AER</em> 1994；Abadie, Diamond and Hainmueller, <em>JASA</em> 2010；Finkelstein 等, <em>QJE</em> 2012；Callaway and Sant&#39;Anna 2021；Card, Kluve and Weber, <em>JEP</em> 2018。</li></ul>',6))])}const C=s(p,[["render",D]]);export{g as __pageData,C as default};
